import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"个人领地","description":"","frontmatter":{},"headers":[],"relativePath":"towns/PersonalClaims.md","filePath":"towns/PersonalClaims.md"}'),s={name:"towns/PersonalClaims.md"};function n(c,t,l,i,r,p){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="个人领地" tabindex="-1">个人领地 <a class="header-anchor" href="#个人领地" aria-label="Permalink to &quot;个人领地&quot;">​</a></h1><p>个人领地（家园领地）是你<strong>唯一的居所</strong>：每人 1 块，个人专属，保护你的建筑与资源——别人无法破坏方块、打开箱子、偷走物品。永不因联盟变动受影响。</p><blockquote><p>由服务器自研插件 <strong>PepperClaim</strong> 提供。想和伙伴一起建公共设施？见<a href="./GuildClaims.html">联盟领地</a>。</p></blockquote><h2 id="圈地规则" tabindex="-1">圈地规则 <a class="header-anchor" href="#圈地规则" aria-label="Permalink to &quot;圈地规则&quot;">​</a></h2><ul><li>领地<strong>不能重叠</strong>。</li><li>出生点 <strong>100 格</strong>范围内无法圈地。</li><li><strong>主城区域</strong>内无法圈地。</li><li>未启用圈地的世界无法圈地。</li><li>圈地操作有<strong>限流</strong>（创建冷却 30 秒），请勿连续快速操作。</li></ul><h2 id="一键安家-新手推荐" tabindex="-1">一键安家（新手推荐） <a class="header-anchor" href="#一键安家-新手推荐" aria-label="Permalink to &quot;一键安家（新手推荐）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim auto</span></span></code></pre></div><p>以你为中心自动圈一块 <strong>16×16</strong> 的家园领地（60 秒冷却），确认后立刻生效，方块、箱子、动物全部受保护。</p><h2 id="手动圈地" tabindex="-1">手动圈地 <a class="header-anchor" href="#手动圈地" aria-label="Permalink to &quot;手动圈地&quot;">​</a></h2><ol><li>拿一把<strong>金锄</strong>（如果背包里没有，可以找管理员领取）。</li><li><strong>左键</strong>点一个角（pos1），走到对角<strong>右键</strong>点另一个角（pos2）。</li><li>看提示：绿色粒子轮廓 = 位置合法；红色 = 冲突（重叠、离出生点太近等），ActionBar 会告诉你原因。</li><li>输入创建：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim create 我的家</span></span></code></pre></div><blockquote><p><strong>引号规则</strong>：大部分命令直接输中文领地名即可（<code>tp</code> / <code>select</code> / <code>create</code> / <code>resize</code> / <code>delete</code> / <code>info</code> 等）；但 <code>rename</code>、<code>set preset</code>、<code>flag</code>、<code>group</code> 这几个命令的领地名参数<strong>需要加引号</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim rename &quot;我的家&quot; 新名字</span></span>
<span class="line"><span>/pclaim flag &quot;我的家&quot; build DENY</span></span></code></pre></div></blockquote><h2 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/pclaim home</code></td><td>传送回家园领地</td></tr><tr><td><code>/pclaim list [页数]</code></td><td>我的领地列表</td></tr><tr><td><code>/pclaim info [领地]</code></td><td>查看领地详情（面积、额度、描述、进出消息）</td></tr><tr><td><code>/pclaim map</code></td><td>查看周边领地的聊天色块地图</td></tr><tr><td><code>/pclaim gui</code></td><td>打开图形界面（推荐！）</td></tr><tr><td><code>/pclaim guide</code></td><td>领取游戏内《领地指南》成书</td></tr><tr><td><code>/pclaim help</code></td><td>显示全部可用命令</td></tr><tr><td><code>/pclaim tp [领地]</code></td><td>传送到领地（不填默认自家）</td></tr><tr><td><code>/pclaim settp</code></td><td>把当前脚下设为领地传送点</td></tr><tr><td><code>/pclaim rename &lt;领地&gt; &lt;新名&gt;</code></td><td>重命名</td></tr><tr><td><code>/pclaim delete &lt;领地&gt;</code></td><td>删除领地（确认后额度退还）</td></tr><tr><td><code>/pclaim trapped</code></td><td>被困自救（回到安全点）</td></tr><tr><td><code>/pclaim confirm</code></td><td>确认待执行操作（10 秒窗口）</td></tr></tbody></table><blockquote><p><strong>目标记忆</strong>：命令不带领地名时，按「脚下领地 → 最近访问 → 自家」的顺序自动选择目标。</p></blockquote><h2 id="进出消息" tabindex="-1">进出消息 <a class="header-anchor" href="#进出消息" aria-label="Permalink to &quot;进出消息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/pclaim set welcome &lt;领地&gt; &lt;消息&gt;</code></td><td>设置进入播报（≤64 字）</td></tr><tr><td><code>/pclaim set farewell &lt;领地&gt; &lt;消息&gt;</code></td><td>设置离开播报（≤64 字）</td></tr><tr><td><code>/pclaim set describe &lt;领地&gt; &lt;文本&gt;</code></td><td>设置描述（≤128 字）</td></tr></tbody></table><p>占位符：<code>%name%</code> = 领地名字、<code>%player%</code> = 玩家名。新领地默认自带「欢迎来到 %name% 领地！」。</p><h2 id="一键权限档位-四档预设" tabindex="-1">一键权限档位（四档预设） <a class="header-anchor" href="#一键权限档位-四档预设" aria-label="Permalink to &quot;一键权限档位（四档预设）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim set preset &lt;领地&gt; 半开放</span></span></code></pre></div><table tabindex="0"><thead><tr><th>档位</th><th>陌生人能做什么</th></tr></thead><tbody><tr><td>封闭</td><td>什么都不能（进都进不来）</td></tr><tr><td>半开放</td><td>能走进领地，但不能用东西、不能破坏</td></tr><tr><td>开放</td><td>能进出、能用公共设施（门/工作台）、能传送到领地，但不能破坏、不能开箱</td></tr><tr><td>亲密</td><td>同封闭，只给最信任的人（组）留门</td></tr></tbody></table><blockquote><p>档位是&quot;一键模板&quot;，切换后仍可用 <code>/pclaim flag</code> 微调单个旗标，互不影响。</p></blockquote><h2 id="旗标-细粒度保护" tabindex="-1">旗标（细粒度保护） <a class="header-anchor" href="#旗标-细粒度保护" aria-label="Permalink to &quot;旗标（细粒度保护）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim flag &lt;领地&gt; pvp DENY           # 领地内禁止玩家互殴</span></span>
<span class="line"><span>/pclaim flag &lt;领地&gt; animalkilling DENY # 禁止杀动物</span></span>
<span class="line"><span>/pclaim flag &lt;领地&gt; build ALLOW        # 允许陌生人建造（慎用）</span></span></code></pre></div><p><strong>常用旗标：</strong></p><table tabindex="0"><thead><tr><th>旗标</th><th>作用</th></tr></thead><tbody><tr><td><code>move</code></td><td>进入领地</td></tr><tr><td><code>use</code></td><td>使用物品/开关（门、按钮、工作台等）</td></tr><tr><td><code>build</code></td><td>建造/破坏方块</td></tr><tr><td><code>container</code></td><td>打开箱子等容器</td></tr><tr><td><code>tp</code></td><td>被传送到领地</td></tr><tr><td><code>riding</code></td><td>骑乘（马、船等）</td></tr><tr><td><code>leash</code></td><td>拴绳</td></tr><tr><td><code>shear</code></td><td>剪羊毛</td></tr><tr><td><code>harvest</code></td><td>收获作物</td></tr><tr><td><code>animalkilling</code></td><td>击杀动物</td></tr><tr><td><code>mobkilling</code></td><td>击杀怪物</td></tr><tr><td><code>pvp</code></td><td>玩家互殴</td></tr><tr><td><code>vehicledestroy</code></td><td>破坏载具</td></tr><tr><td><code>firespread</code></td><td>火焰蔓延</td></tr><tr><td><code>nomobs</code></td><td>禁止怪物生成</td></tr></tbody></table><p>取值：<code>ALLOW</code>（允许）/ <code>DENY</code>（禁止）/ <code>unset</code>（恢复默认）。</p><blockquote><p>⚠️ <strong>极性注意</strong>：<code>nomobs</code>、<code>pistonprotection</code>、<code>flowinprotection</code> 三个旗标在本服是 <strong><code>DENY</code> = 生效</strong>。例如&quot;禁怪&quot;写 <code>nomobs DENY</code>。</p></blockquote><h2 id="角色组-精细授权" tabindex="-1">角色组（精细授权） <a class="header-anchor" href="#角色组-精细授权" aria-label="Permalink to &quot;角色组（精细授权）&quot;">​</a></h2><p>给特定玩家开小灶——建组、把人放进组、给组设旗标：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim group &lt;领地&gt; create 室友        # 建组（每块领地最多 4 组）</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; assign 张三 室友    # 把玩家放进组</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; setflag 室友 container ALLOW  # 组旗标</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; list               # 查看</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; unassign 张三 室友  # 移出组</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; delete 室友         # 删除组</span></span></code></pre></div><h2 id="黑名单" tabindex="-1">黑名单 <a class="header-anchor" href="#黑名单" aria-label="Permalink to &quot;黑名单&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim ban 捣蛋鬼       # 拉黑后无法进入你的领地</span></span>
<span class="line"><span>/pclaim unban 捣蛋鬼</span></span></code></pre></div><h2 id="保护机制" tabindex="-1">保护机制 <a class="header-anchor" href="#保护机制" aria-label="Permalink to &quot;保护机制&quot;">​</a></h2><ul><li><strong>死亡掉落锁定</strong>：在领地内死亡，你的掉落物有 <strong>60 秒</strong>锁定时间，只有你能拾取。</li><li><strong>安全传送</strong>：传送到领地会自动计算安全落点（避开实心方块、岩浆、虚空），计算失败会拒绝传送。</li><li><strong>传送冷却</strong>：领地传送有 30 秒冷却。</li></ul><h2 id="额度与经济" tabindex="-1">额度与经济 <a class="header-anchor" href="#额度与经济" aria-label="Permalink to &quot;额度与经济&quot;">​</a></h2><p>领地大小受<strong>额度</strong>限制（方块数）：</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/pclaim quota</code></td><td>查看剩余额度</td></tr><tr><td><code>/pclaim buy &lt;块数&gt;</code></td><td>用游戏币购买个人额度</td></tr></tbody></table><p>额度不够时 <code>resize</code> / <code>create</code> 会被拒绝并提示缺口。删除领地后额度<strong>全额退还</strong>。</p><h2 id="扩展与调整选区" tabindex="-1">扩展与调整选区 <a class="header-anchor" href="#扩展与调整选区" aria-label="Permalink to &quot;扩展与调整选区&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim select 我的家                 # 把已有领地的范围加载为当前选区</span></span>
<span class="line"><span>/pclaim expand 5 north                # 朝北扩 5 格（north/south/east/west）</span></span>
<span class="line"><span>/pclaim expand 10 out                 # 四周各扩 10 格</span></span>
<span class="line"><span>/pclaim expand 10                     # 朝你面向的方向扩 10 格</span></span>
<span class="line"><span>/pclaim expand -3 east                # 负数是收缩（最少 1 格宽）</span></span>
<span class="line"><span>/pclaim resize 我的家                 # 用当前选区扩大/缩小领地</span></span></code></pre></div><blockquote><p>⚠️ <code>resize</code> 后 <strong>72 小时冷却</strong>（扩和缩都算）；扩边只扣<strong>增量</strong>额度，缩地退换额度。</p></blockquote><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：领地被人破坏了？</strong> 先检查 <code>move</code> / <code>build</code> / <code>container</code> 旗标是否被误设为 <code>ALLOW</code>：<code>/pclaim flag &lt;领地&gt; build DENY</code> 恢复。</p><p><strong>Q：陌生人能传送到我的领地？</strong> 检查 <code>tp</code> 旗标（半开放档默认 <code>DENY</code>）：<code>/pclaim flag &lt;领地&gt; tp DENY</code>。</p><p><strong>Q：为什么杀不了领地里的动物？</strong><code>animalkilling</code> 半开放档默认 <code>DENY</code>——这是保护。要开放：<code>/pclaim flag &lt;领地&gt; animalkilling ALLOW</code>。</p><p><strong>Q：resize 提示冷却？</strong> 72 小时内只能改一次，等冷却结束或接受现状。</p><p><strong>Q：中文领地名报错？</strong><code>rename</code>、<code>set preset</code>、<code>flag</code>、<code>group</code> 命令的领地名参数需要加引号：<code>/pclaim rename &quot;我的家&quot; 新名字</code>。</p><p><strong>Q：想换个档位但不想动旗标？</strong> 档位是一键模板，切换后可用 <code>/pclaim flag</code> 微调。</p><p><strong>Q：伙伴进不来基地？</strong> 把他加进角色组并给组开 <code>move</code> 旗标，或使用「半开放/开放」档位。</p><h2 id="市场" tabindex="-1">市场 <a class="header-anchor" href="#市场" aria-label="Permalink to &quot;市场&quot;">​</a></h2><blockquote><p>当前服务器的租赁（<code>rent</code>）与拍卖（<code>auction</code>）功能<strong>未开放</strong>，如提示&quot;该功能已在服务器配置中禁用&quot;即属正常。</p></blockquote>`,52)])])}const u=e(s,[["render",n]]);export{g as __pageData,u as default};
